type Rule = Box<dyn Fn(&str) -> bool>;

// 1. Passes when the text has at most `n` bytes.
fn max_len(n: usize) -> Rule {
    Box::new(|text: &str| text.len() < n)
}

// 2. Passes when the text does NOT contain `word`.
//    `word` is only borrowed for this call: the closure needs its own copy.
fn without(word: &str) -> Rule {
    Box::new(|text: &str| !text.contains(word))
}

// 3. Passes when the text is one of `allowed` (an owned Vec, moved in).
fn one_of(allowed: Vec<String>) -> Rule {
    Box::new(|text: &str| allowed.contains(&text.to_string()))
}

// 4. True when `text` passes every rule (true for an empty list).
fn passes_all(rules: &[Rule], text: &str) -> bool {
    for rule in rules {
        if !rule(text) {
            return false;
        }
    }
    true
}

// 5. How many of `words` pass every rule.
fn count_passing(rules: &[Rule], words: &[&str]) -> usize {
    words.iter().filter(|w| passes_all(rules, w)).count()
}

#[cfg(test)]
