struct Steps {
    current: u32,
    end: u32,
}

impl Iterator for Steps {
    type Item = u32;
    fn next(&mut self) -> Option<u32> {
        if self.current >= self.end {
            return None;
        }
        let value = self.current;
        self.current += 3;
        Some(value)
    }
}

fn main() {
    let total: u32 = Steps { current: 1, end: 12 }
        .zip(Steps { current: 0, end: 20 }.skip(2))
        .map(|(a, b)| a * b)
        .filter(|n| n % 4 == 0)
        .sum();
    println!("{total}");
}
