// Each call of the returned closure should give the next label:
// make_labeler("disk", 7) gives "DISK-8", then "DISK-9", ...
fn make_labeler(kind: &str, start: u32) -> impl FnMut() -> String {
    let prefix = kind.to_uppercase();
    let mut next = start;
    move || {
        next += 1;
        format!("{prefix}-{next}")
    }
}

fn main() {
    let mut disk = make_labeler("disk", 7);
    let mut net = make_labeler("net", 0);
    println!("{} {} {}", disk(), disk(), net());
}

