'use server';

import { parseSettings, putSettings } from '@/lib/settings';

export type SaveState =
  | { status: 'idle' }
  | { status: 'saved'; savedAt: string }
  | { status: 'invalid'; errors: Record<string, string> };

export async function saveSettings(_prev: SaveState, formData: FormData): Promise<SaveState> {
  const parsed = parseSettings(formData);
  if (!parsed.ok) {
    return { status: 'invalid', errors: parsed.errors };
  }

  await putSettings(parsed.values);

  return { status: 'saved', savedAt: new Date().toISOString() };
}

