type BaseField = { key: string; label: string; optional?: boolean };

export type FieldDef =
  | (BaseField & { type: 'number'; min: number; max: number; step?: number; unit?: string })
  | (BaseField & { type: 'select'; options: { value: string; label: string }[] })
