'use client';

import { useActionState } from 'react';
import { useAccount } from '../account-provider';
import type { FieldDef, SettingsSchema, SettingsValues } from '@/lib/settings-schema';
import { saveSettings, type SaveState } from './actions';

function Field({ field, value, error, disabled }: { field: FieldDef; value: string | number | undefined; error?: string; disabled: boolean }) {
  const common = { id: field.key, name: field.key, defaultValue: value ?? '', disabled };
  return (
    <div className={error ? 'field has-error' : 'field'}>
      <label htmlFor={field.key}>{field.label}</label>
      {field.type === 'number' && (
        <input type="number" min={field.min} max={field.max} step={field.step ?? 1} {...common} />
      )}
      {field.type === 'select' && (
        <select {...common}>
          {field.options.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
      )}
      {field.type === 'text' && <input type="text" maxLength={field.maxLength} {...common} />}
      {error && <span className="error">{error}</span>}
    </div>
  );
}

export function SettingsForm({ schema, values }: { schema: SettingsSchema; values: SettingsValues }) {
  const account = useAccount();
  const canEdit = account?.role === 'editor';
  const [state, formAction, pending] = useActionState<SaveState, FormData>(saveSettings, { status: 'idle' });
  const errors = state.status === 'invalid' ? state.errors : {};

  return (
    <form action={formAction} className="settings-form">
      {schema.groups.map((group) => (
        <fieldset key={group.id}>
          <legend>{group.title}</legend>
          {group.fields.map((field) => (
            <Field key={field.key} field={field} value={values[field.key]} error={errors[field.key]} disabled={!canEdit} />
          ))}
        </fieldset>
      ))}
      <div className="actions">
        {canEdit && (
          <button type="submit" disabled={pending}>
            {pending ? 'Saving…' : 'Save'}
          </button>
        )}
        {state.status === 'saved' && (
          <span className="toast" role="status">
            Saved at {new Date(state.savedAt).toLocaleTimeString('en-GB')}
          </span>
        )}
      </div>
    </form>
  );
}

