// SPDX-License-Identifier: GPL-2.0
/*
 * Two ADCs on I2C2 (Linux bus 1). Their open-drain RDY outputs are wired
 * together to GPIO1_IO17, with a 10 kohm pull-up to 3.3 V.
 */

&i2c2 {
	clock-frequency = <400000>;
	status = "okay";

	adc@48 {
		compatible = "qadc4";
		reg = <0x48>;
		interrupt-parent = <&gpio1>;
		interrupts = <17 IRQ_TYPE_LEVEL_LOW>;
	};

	adc@49 {
		compatible = "qadc4";
		reg = <0x49>;
		interrupt-parent = <&gpio1>;
		interrupts = <17 IRQ_TYPE_LEVEL_LOW>;
	};
};

--- qadc-core.c ---
// SPDX-License-Identifier: GPL-2.0
/*
 * Driver for a 4-channel, 16-bit I2C ADC with a data-ready (RDY) output.
 *
 * RDY is open-drain and active low. It goes low when a conversion result
 * is ready and stays low until the result is read (see README.md).
 */

#include <linux/bitfield.h>
#include <linux/delay.h>
#include <linux/device.h>
#include <linux/i2c.h>
#include <linux/interrupt.h>
#include <linux/jiffies.h>
#include <linux/kernel.h>
#include <linux/ktime.h>
#include <linux/module.h>

#include "qadc.h"

static const unsigned int qadc_odr_hz[] = { 0, 25, 50, 100, 250, 500, 1000 };

bool qadc_odr_valid(unsigned int odr_hz)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(qadc_odr_hz); i++)
		if (qadc_odr_hz[i] == odr_hz)
			return true;
	return false;
}

/* Caller holds cfg_lock. */
int qadc_hw_config(struct qadc *st, unsigned int odr_hz)
{
	u8 cfg = 0;
	int i;

	for (i = 1; i < ARRAY_SIZE(qadc_odr_hz); i++)
		if (qadc_odr_hz[i] == odr_hz)
			cfg = QADC_CONFIG_CONT | FIELD_PREP(QADC_CONFIG_ODR_MASK, i);

	return i2c_smbus_write_byte_data(st->client, QADC_REG_CONFIG, cfg);
}

/* How long the watchdog waits for a conversion, in jiffies. */
unsigned long qadc_wdog_period(struct qadc *st)
{
	unsigned int hz;

	mutex_lock(&st->cfg_lock);
	hz = st->odr_hz;
	mutex_unlock(&st->cfg_lock);

	if (!hz)
		return MAX_JIFFY_OFFSET;
	return msecs_to_jiffies(QADC_WDOG_MISSED * MSEC_PER_SEC / hz) + 1;
}

void qadc_wdog_kick(struct qadc *st)
{
	mod_timer(&st->wdog, jiffies + qadc_wdog_period(st));
}

static irqreturn_t qadc_hardirq(int irq, void *data)
{
	struct qadc *st = data;

	spin_lock(&st->lock);
	st->irq_ts_ns = ktime_get_ns();
	st->irqs++;
	spin_unlock(&st->lock);

	qadc_wdog_kick(st);

	return IRQ_WAKE_THREAD;
}

static irqreturn_t qadc_irq_thread(int irq, void *data)
{
	struct qadc *st = data;
	struct qadc_sample *s;
	__be16 raw[QADC_NUM_CH];
	unsigned long flags;
	int ret, i;

	ret = i2c_smbus_read_i2c_block_data(st->client, QADC_REG_DATA,
					    sizeof(raw), (u8 *)raw);
	if (ret != sizeof(raw)) {
		dev_err_ratelimited(st->dev, "data read failed: %d\n", ret);
		return IRQ_HANDLED;
	}

	spin_lock_irqsave(&st->lock, flags);
	s = &st->ring[st->head];
	s->ts_ns = st->irq_ts_ns;
	for (i = 0; i < QADC_NUM_CH; i++)
		s->ch[i] = be16_to_cpu(raw[i]);
	st->head = (st->head + 1) & (QADC_RING_LEN - 1);
	st->samples++;
	spin_unlock_irqrestore(&st->lock, flags);

	return IRQ_HANDLED;
}

static void qadc_wdog_expired(struct timer_list *t)
{
	struct qadc *st = from_timer(st, t, wdog);

	spin_lock(&st->lock);
	st->resets++;
	spin_unlock(&st->lock);

	dev_warn(st->dev, "no conversion for %d periods, resetting\n",
		 QADC_WDOG_MISSED);
	schedule_work(&st->reset_work);
}

static void qadc_reset_work(struct work_struct *work)
{
	struct qadc *st = container_of(work, struct qadc, reset_work);
	int ret;

	mutex_lock(&st->cfg_lock);
	ret = qadc_hw_config(st, 0);
	if (!ret) {
		usleep_range(100, 200);
		ret = qadc_hw_config(st, st->odr_hz);
	}
	mutex_unlock(&st->cfg_lock);

	if (ret)
		dev_err(st->dev, "reset failed: %d\n", ret);

	qadc_wdog_kick(st);
}

static int qadc_probe(struct i2c_client *client)
{
	struct device *dev = &client->dev;
	struct qadc *st;
	int ret;

	st = devm_kzalloc(dev, sizeof(*st), GFP_KERNEL);
	if (!st)
		return -ENOMEM;

	st->client = client;
	st->dev = dev;
	i2c_set_clientdata(client, st);
	mutex_init(&st->cfg_lock);
	spin_lock_init(&st->lock);

	ret = i2c_smbus_read_byte_data(client, QADC_REG_ID);
	if (ret < 0)
		return dev_err_probe(dev, ret, "cannot read ID\n");
	if (ret != QADC_ID_VALUE)
		return dev_err_probe(dev, -ENODEV, "unexpected ID 0x%02x\n", ret);

	if (client->irq <= 0)
		return dev_err_probe(dev, -EINVAL, "no RDY interrupt\n");

	/*
	 * Both ADCs drive the same RDY line (see dts/), so the IRQ is shared.
	 * request_threaded_irq() refuses a NULL primary handler here
	 * ("Threaded irq requested with handler=NULL and !ONESHOT"),
	 * so we pass qadc_hardirq.
	 */
	ret = devm_request_threaded_irq(dev, client->irq, qadc_hardirq,
					qadc_irq_thread, IRQF_SHARED,
					dev_name(dev), st);
	if (ret)
		return dev_err_probe(dev, ret, "cannot request IRQ %d\n",
				     client->irq);

	timer_setup(&st->wdog, qadc_wdog_expired, 0);
	INIT_WORK(&st->reset_work, qadc_reset_work);

	mutex_lock(&st->cfg_lock);
	st->odr_hz = QADC_DEFAULT_ODR_HZ;
	ret = qadc_hw_config(st, st->odr_hz);
	mutex_unlock(&st->cfg_lock);
	if (ret)
		return dev_err_probe(dev, ret, "cannot start conversions\n");

	qadc_wdog_kick(st);

	dev_info(dev, "%d channels, %u Hz, irq %d\n", QADC_NUM_CH,
		 st->odr_hz, client->irq);
	return 0;
}

static void qadc_remove(struct i2c_client *client)
{
	struct qadc *st = i2c_get_clientdata(client);

	mutex_lock(&st->cfg_lock);
	qadc_hw_config(st, 0);
	mutex_unlock(&st->cfg_lock);

	del_timer(&st->wdog);
}

static const struct i2c_device_id qadc_id[] = {
	{ "qadc4" },
	{ }
};
MODULE_DEVICE_TABLE(i2c, qadc_id);

static struct i2c_driver qadc_driver = {
	.driver = {
		.name = "qadc",
		.dev_groups = qadc_groups,
	},
	.probe = qadc_probe,
	.remove = qadc_remove,
	.id_table = qadc_id,
};
module_i2c_driver(qadc_driver);

MODULE_DESCRIPTION("4-channel I2C ADC with data-ready interrupt");
MODULE_LICENSE("GPL");

--- qadc-sysfs.c ---
// SPDX-License-Identifier: GPL-2.0
/*
 * sysfs attributes, one set per ADC:
 *   latest  newest sample: "<timestamp ns> <ch0> <ch1> <ch2> <ch3>"
 *   stats   sample, interrupt and watchdog reset counters
 *   odr     conversion rate in Hz
 */

#include <linux/device.h>
#include <linux/kernel.h>
#include <linux/kstrtox.h>
#include <linux/mutex.h>
#include <linux/spinlock.h>
#include <linux/sysfs.h>

#include "qadc.h"

static ssize_t latest_show(struct device *dev, struct device_attribute *attr,
			   char *buf)
{
	struct qadc *st = dev_get_drvdata(dev);
	struct qadc_sample s;

	spin_lock(&st->lock);
	s = st->ring[(st->head - 1) & (QADC_RING_LEN - 1)];
	spin_unlock(&st->lock);

	return sysfs_emit(buf, "%llu %u %u %u %u\n", s.ts_ns,
			  s.ch[0], s.ch[1], s.ch[2], s.ch[3]);
}
static DEVICE_ATTR_RO(latest);

static ssize_t stats_show(struct device *dev, struct device_attribute *attr,
			  char *buf)
{
	struct qadc *st = dev_get_drvdata(dev);

	return sysfs_emit(buf, "samples %llu\nirqs %lu\nresets %lu\n",
			  st->samples, st->irqs, st->resets);
}
static DEVICE_ATTR_RO(stats);

static ssize_t odr_show(struct device *dev, struct device_attribute *attr,
			char *buf)
{
	struct qadc *st = dev_get_drvdata(dev);
	unsigned int hz;

	mutex_lock(&st->cfg_lock);
	hz = st->odr_hz;
	mutex_unlock(&st->cfg_lock);

	return sysfs_emit(buf, "%u\n", hz);
}

static ssize_t odr_store(struct device *dev, struct device_attribute *attr,
			 const char *buf, size_t count)
{
	struct qadc *st = dev_get_drvdata(dev);
	unsigned int hz;
	int ret;

	ret = kstrtouint(buf, 0, &hz);
	if (ret)
		return ret;
	if (!qadc_odr_valid(hz))
		return -EINVAL;

	mutex_lock(&st->cfg_lock);
	ret = qadc_hw_config(st, hz);
	if (!ret)
		st->odr_hz = hz;
	mutex_unlock(&st->cfg_lock);
	if (ret)
		return ret;

	qadc_wdog_kick(st);
	return count;
}
static DEVICE_ATTR_RW(odr);

static struct attribute *qadc_attrs[] = {
	&dev_attr_latest.attr,
	&dev_attr_stats.attr,
	&dev_attr_odr.attr,
	NULL
};

static const struct attribute_group qadc_group = {
	.attrs = qadc_attrs,
};

const struct attribute_group *qadc_groups[] = {
	&qadc_group,
	NULL
};

