 qadc-core.c  | 46 ++++++++++++++++++----------------------------
 qadc-sysfs.c |  5 ++---
 qadc.h       |  4 +---
 3 files changed, 21 insertions(+), 34 deletions(-)

diff --git a/qadc-core.c b/qadc-core.c
index baf8f28..419361c 100644
--- a/qadc-core.c
+++ b/qadc-core.c
@@ -62,26 +62,12 @@ void qadc_wdog_kick(struct qadc *st)
 	mod_timer(&st->wdog, jiffies + qadc_wdog_period(st));
 }

-static irqreturn_t qadc_hardirq(int irq, void *data)
-{
-	struct qadc *st = data;
-
-	spin_lock(&st->lock);
-	st->irq_ts_ns = ktime_get_ns();
-	st->irqs++;
-	spin_unlock(&st->lock);
-
-	qadc_wdog_kick(st);
-
-	return IRQ_WAKE_THREAD;
-}
-
 static irqreturn_t qadc_irq_thread(int irq, void *data)
 {
 	struct qadc *st = data;
 	struct qadc_sample *s;
 	__be16 raw[QADC_NUM_CH];
-	unsigned long flags;
+	u64 ts = ktime_get_ns();
 	int ret, i;

 	ret = i2c_smbus_read_i2c_block_data(st->client, QADC_REG_DATA,
@@ -91,14 +77,17 @@ static irqreturn_t qadc_irq_thread(int irq, void *data)
 		return IRQ_HANDLED;
 	}

