Date: Fri, 2 Oct 2026 16:41:07 +0000
Subject: [PATCH] qadc: move all interrupt work to the IRQ thread

The debug kernel complains about the hard handler (might_sleep and lockdep,
both on the mutex taken from qadc_hardirq), and lockdep also reports st->lock
taken from sysfs with interrupts enabled.

Drop qadc_hardirq and do everything in the IRQ thread, with a NULL primary
handler and IRQF_ONESHOT, which the core now accepts. The timestamp is taken
at the start of the thread.

Nothing touches st->lock from hard interrupt context any more, so make it a
mutex everywhere: the IRQ thread, sysfs and the watchdog.

On remove, cancel the reset work and delete the watchdog timer before
stopping conversions.

Tested on the debug kernel:
- /proc/interrupts: about 200 interrupts per second on line 63
- tests/stall_test.sh 1-0048 1-0049: PASS
- tests/unbind_loop.sh 1-0048 50: 50 of 50, no crash
---
 qadc-core.c  | 46 ++++++++++++++++++----------------------------
 qadc-sysfs.c |  5 ++---
 qadc.h       |  4 +---
 3 files changed, 21 insertions(+), 34 deletions(-)

diff --git a/qadc-core.c b/qadc-core.c
index baf8f28..419361c 100644
--- a/qadc-core.c
+++ b/qadc-core.c
@@ -62,26 +62,12 @@ void qadc_wdog_kick(struct qadc *st)
 	mod_timer(&st->wdog, jiffies + qadc_wdog_period(st));
 }

-static irqreturn_t qadc_hardirq(int irq, void *data)
-{
-	struct qadc *st = data;
-
-	spin_lock(&st->lock);
-	st->irq_ts_ns = ktime_get_ns();
-	st->irqs++;
-	spin_unlock(&st->lock);
-
-	qadc_wdog_kick(st);
-
-	return IRQ_WAKE_THREAD;
-}
-
 static irqreturn_t qadc_irq_thread(int irq, void *data)
 {
 	struct qadc *st = data;
 	struct qadc_sample *s;
 	__be16 raw[QADC_NUM_CH];
-	unsigned long flags;
+	u64 ts = ktime_get_ns();
 	int ret, i;

 	ret = i2c_smbus_read_i2c_block_data(st->client, QADC_REG_DATA,
@@ -91,14 +77,17 @@ static irqreturn_t qadc_irq_thread(int irq, void *data)
 		return IRQ_HANDLED;
 	}

-	spin_lock_irqsave(&st->lock, flags);
+	mutex_lock(&st->lock);
+	st->irqs++;
 	s = &st->ring[st->head];
-	s->ts_ns = st->irq_ts_ns;
+	s->ts_ns = ts;
 	for (i = 0; i < QADC_NUM_CH; i++)
 		s->ch[i] = be16_to_cpu(raw[i]);
 	st->head = (st->head + 1) & (QADC_RING_LEN - 1);
 	st->samples++;
-	spin_unlock_irqrestore(&st->lock, flags);
+	mutex_unlock(&st->lock);
+
+	qadc_wdog_kick(st);

 	return IRQ_HANDLED;
 }
@@ -107,9 +96,9 @@ static void qadc_wdog_expired(struct timer_list *t)
 {
 	struct qadc *st = from_timer(st, t, wdog);

-	spin_lock(&st->lock);
+	mutex_lock(&st->lock);
 	st->resets++;
-	spin_unlock(&st->lock);
+	mutex_unlock(&st->lock);

 	dev_warn(st->dev, "no conversion for %d periods, resetting\n",
 		 QADC_WDOG_MISSED);
@@ -149,7 +138,7 @@ static int qadc_probe(struct i2c_client *client)
 	st->dev = dev;
 	i2c_set_clientdata(client, st);
 	mutex_init(&st->cfg_lock);
-	spin_lock_init(&st->lock);
+	mutex_init(&st->lock);

 	ret = i2c_smbus_read_byte_data(client, QADC_REG_ID);
 	if (ret < 0)
@@ -162,12 +151,12 @@ static int qadc_probe(struct i2c_client *client)

 	/*
 	 * Both ADCs drive the same RDY line (see dts/), so the IRQ is shared.
-	 * request_threaded_irq() refuses a NULL primary handler here
-	 * ("Threaded irq requested with handler=NULL and !ONESHOT"),
-	 * so we pass qadc_hardirq.
+	 * All the work, the I2C read included, is done in the IRQ thread;
+	 * IRQF_ONESHOT keeps the line masked until the threads have run.
 	 */
-	ret = devm_request_threaded_irq(dev, client->irq, qadc_hardirq,
-					qadc_irq_thread, IRQF_SHARED,
+	ret = devm_request_threaded_irq(dev, client->irq, NULL,
+					qadc_irq_thread,
+					IRQF_SHARED | IRQF_ONESHOT,
 					dev_name(dev), st);
 	if (ret)
 		return dev_err_probe(dev, ret, "cannot request IRQ %d\n",
@@ -194,11 +183,12 @@ static void qadc_remove(struct i2c_client *client)
 {
 	struct qadc *st = i2c_get_clientdata(client);

+	cancel_work_sync(&st->reset_work);
+	del_timer_sync(&st->wdog);
+
 	mutex_lock(&st->cfg_lock);
 	qadc_hw_config(st, 0);
 	mutex_unlock(&st->cfg_lock);
-
-	del_timer(&st->wdog);
 }

 static const struct i2c_device_id qadc_id[] = {
