package com.example.vms.portal.projection;

import com.example.vms.portal.view.InvoiceStatus;
import com.example.vms.portal.view.VendorInvoiceView;
import com.example.vms.portal.view.VendorInvoiceViewRepository;
import com.azure.messaging.servicebus.ServiceBusReceivedMessageContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Keeps vendor_invoice_view in step with ERP payment events.
 * Topic erp-payment-events, subscription vms-portal, PEEK_LOCK. Runs on 2 replicas.
 */
@Component
public class PaymentStatusProjection {

    private static final Logger log = LoggerFactory.getLogger(PaymentStatusProjection.class);

    private final VendorInvoiceViewRepository views;
    private final ObjectMapper json;
    private final Set<String> seen = ConcurrentHashMap.newKeySet();

    public PaymentStatusProjection(VendorInvoiceViewRepository views, ObjectMapper json) {
        this.views = views;
        this.json = json;
    }

    public record PaymentEvent(String businessEventId, String eventType, long controlNumber,
                               Instant eventTime, String legalEntity, String journalNum,
                               String paymentRunId, String vendAccount, List<String> invoices) {}

    @Transactional
    public void onMessage(ServiceBusReceivedMessageContext context) throws Exception {
        var event = json.readValue(context.getMessage().getBody().toBytes(), PaymentEvent.class);
        var prefix = "%s BusinessEventId=%s ControlNumber=%d JournalNum=%s PaymentRunId=%s Invoices=%s".formatted(
                event.eventType(), event.businessEventId(), event.controlNumber(), event.journalNum(),
                event.paymentRunId(), event.invoices());

        if (!seen.add(event.businessEventId())) {
            log.info("{} -> duplicate BusinessEventId, skipped", prefix);
            context.complete();
            return;
        }
        context.complete();

        var invoiceId = event.invoices().get(0);
        VendorInvoiceView view = views.findById(invoiceId)
                .orElseThrow(() -> new IllegalStateException("no view row for " + invoiceId));

        view.setStatus(map(event.eventType()));
        view.setLastJournal(event.journalNum());
        view.setUpdatedAt(Instant.now());
        views.save(view);

        log.info("{} -> applied invoice={} status={}", prefix, invoiceId, view.getStatus());
    }

    private static InvoiceStatus map(String eventType) {
        return switch (eventType) {
            case "VendPaymentPosted" -> InvoiceStatus.PAID;
            case "VendPaymentReversed" -> InvoiceStatus.APPROVED;
            default -> throw new IllegalArgumentException("unknown event type " + eventType);
        };
    }
}


