// SPDX-License-Identifier: GPL-2.0
/*
 * capcheck: check frames from /dev/adc-capture0 with the block in test-pattern
 * mode (insmod adc_capture.ko test_pattern=1).
 *
 * In test-pattern mode word i of frame n is (n & 0xffff) << 16 | i. For each
 * wrong word capcheck works out which frame it came from: the "age" is how
 * many frames older that frame is than the one being read.
 *
 * usage: capcheck [-n frames] [-v frames_to_print] [device]
 */
#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "../uapi/adc_capture.h"

#define FRAME_BYTES	65536
#define FRAME_WORDS	(FRAME_BYTES / 4)
#define RECORD_BYTES	(sizeof(struct adc_capture_hdr) + FRAME_BYTES)
#define RUNS_SHOWN	6
#define MAX_AGE		64

struct totals {
	uint64_t frames, bad_frames, bad_words, zero_words, other_words;
	uint64_t age[MAX_AGE + 1];	/* [MAX_AGE] = older */
	uint64_t runs, run_len[3];	/* 8 words, 16 words, other */
	uint64_t gaps, lost, short_frames;
};

static int read_record(int fd, uint8_t *buf)
{
	size_t got = 0;

	while (got < RECORD_BYTES) {
		ssize_t r = read(fd, buf + got, RECORD_BYTES - got);

		if (r < 0 && errno == EINTR)
			continue;
		if (r <= 0)
			return r < 0 ? -1 : 0;
		got += r;
	}
	return 1;
}

static void check_frame(const struct adc_capture_hdr *h, const uint32_t *w,
			struct totals *t, int print)
{
	uint32_t tag = h->seq & 0xffff;
	uint64_t bad = 0;
	int runs = 0, shown = 0, i = 0;
	char line[512];
	int len = 0;

	while (i < FRAME_WORDS) {
		uint32_t want = tag << 16 | i;

		if (w[i] == want) {
			i++;
			continue;
		}

		/* a run of wrong words; classify it by its first word */
		int start = i;
		uint32_t first = w[i];

		while (i < FRAME_WORDS && w[i] != (tag << 16 | (uint32_t)i)) {
			uint32_t v = w[i];

			if (v == 0) {
				t->zero_words++;
			} else if ((v & 0xffff) == (uint32_t)i) {
				uint32_t age = (tag - (v >> 16)) & 0xffff;

				t->age[age < MAX_AGE ? age : MAX_AGE]++;
			} else {
				t->other_words++;
			}
			bad++;
			i++;
		}
		runs++;
		t->runs++;
		t->run_len[i - start == 8 ? 0 : i - start == 16 ? 1 : 2]++;

		if (print && shown < RUNS_SHOWN) {
			if (first == 0)
				len += snprintf(line + len, sizeof(line) - len,
						"%s%d-%d zero", shown ? ", " : "", start, i - 1);
			else
				len += snprintf(line + len, sizeof(line) - len,
						"%s%d-%d age %u", shown ? ", " : "", start, i - 1,
						(tag - (first >> 16)) & 0xffff);
			shown++;
		}
	}

	if (!bad)
		return;
	t->bad_frames++;
	t->bad_words += bad;
	if (print)
		printf("seq %7" PRIu32 ": %5" PRIu64 " bad words in %4d runs: %s%s\n",
		       h->seq, bad, runs, line, runs > RUNS_SHOWN ? ", ..." : "");
}

int main(int argc, char **argv)
{
	const char *dev = "/dev/adc-capture0";
	uint64_t want = 1000, printed = 0, print_max = 10;
	struct totals t = { 0 };
	int64_t last_seq = -1;
	uint32_t first_seq = 0;
	uint8_t *buf;
	int opt, fd;

	while ((opt = getopt(argc, argv, "n:v:")) != -1) {
		switch (opt) {
		case 'n': want = strtoull(optarg, NULL, 0); break;
		case 'v': print_max = strtoull(optarg, NULL, 0); break;
		default:
			fprintf(stderr, "usage: %s [-n frames] [-v frames_to_print] [device]\n", argv[0]);
			return 2;
		}
	}
	if (optind < argc)
		dev = argv[optind];

	fd = open(dev, O_RDONLY);
	if (fd < 0) {
		perror(dev);
		return 1;
	}
	buf = malloc(RECORD_BYTES);
	if (!buf)
		return 1;

	printf("capcheck: %s, %" PRIu64 " frames, word i of frame n = (n & 0xffff) << 16 | i\n",
	       dev, want);
	while (t.frames < want) {
		const struct adc_capture_hdr *h = (const void *)buf;
		int r = read_record(fd, buf);

		if (r <= 0) {
			fprintf(stderr, "capcheck: read: %s\n", r ? strerror(errno) : "end of file");
			break;
		}
		if (h->bytes != FRAME_BYTES) {
			t.short_frames++;
			continue;
		}
		if (last_seq < 0) {
			first_seq = h->seq;
		} else if (h->seq != (uint32_t)(last_seq + 1)) {
			t.gaps++;
			t.lost += h->seq - (uint32_t)(last_seq + 1);
			printf("seq %7" PRIu32 ": gap, %" PRIu32 " frame(s) missing before it\n",
			       h->seq, h->seq - (uint32_t)(last_seq + 1));
		}
		last_seq = h->seq;
		t.frames++;

		uint64_t before = t.bad_frames;
		check_frame(h, (const uint32_t *)(buf + sizeof(*h)), &t, printed < print_max);
		if (t.bad_frames != before)
			printed++;
	}

	printf("\nframes read        %" PRIu64 " (seq %" PRIu32 " to %" PRId64 "), %" PRIu64
	       " gaps, %" PRIu64 " frames missing, %" PRIu64 " short\n",
	       t.frames, first_seq, last_seq, t.gaps, t.lost, t.short_frames);
	printf("frames with errors %" PRIu64 " (%.2f%%)\n", t.bad_frames,
	       t.frames ? 100.0 * t.bad_frames / t.frames : 0.0);
	printf("bad words          %" PRIu64 " of %" PRIu64 " (%.3f%%)\n", t.bad_words,
	       t.frames * FRAME_WORDS,
	       t.frames ? 100.0 * t.bad_words / (t.frames * FRAME_WORDS) : 0.0);
	printf("  zero             %" PRIu64 "\n", t.zero_words);
	printf("  from an older frame, by age:");
	int any = 0;
	for (int a = 1; a <= MAX_AGE; a++) {
		if (!t.age[a])
			continue;
		printf("%s %s%d: %" PRIu64, any ? "," : "", a == MAX_AGE ? ">=" : "", a, t.age[a]);
		any = 1;
	}
	printf("%s\n", any ? "" : " none");
	printf("  other            %" PRIu64 "\n", t.other_words);
	printf("bad runs           %" PRIu64 " (8 words: %" PRIu64 ", 16 words: %" PRIu64
	       ", other lengths: %" PRIu64 ")\n",
	       t.runs, t.run_len[0], t.run_len[1], t.run_len[2]);
	printf("result             %s\n", t.bad_words || t.lost || t.short_frames ? "FAIL" : "PASS");

	free(buf);
	close(fd);
	return t.bad_words || t.lost || t.short_frames ? 1 : 0;
}

