/* SPDX-License-Identifier: GPL-2.0 */
/*
 * Register map of the ADC capture block, IP version 1.2.
 * See README.md, "Register map", for the full description.
 */
#ifndef _ADC_CAPTURE_REGS_H
#define _ADC_CAPTURE_REGS_H

#include <linux/bits.h>

/* Control and status, AXI-Lite slave */
#define CAP_REG_ID		0x000	/* RO: [31:16] major, [15:0] minor */
#define CAP_REG_CTRL		0x004
#define CAP_REG_STATUS		0x008	/* [2:0] write 1 to clear */
#define CAP_REG_IRQ_EN		0x00c
#define CAP_REG_FRAME_BYTES	0x010
#define CAP_REG_CLKDIV		0x014	/* ADC sample clock = fclk / (CLKDIV + 1) */
#define CAP_REG_FRAME_CNT	0x018	/* RO: frames completed since ENABLE */

/* Descriptor DMA engine */
#define CAP_REG_DESC_BASE	0x100	/* bus address of the ring, 32 bits */
#define CAP_REG_DESC_COUNT	0x104	/* number of descriptors in the ring */
#define CAP_REG_DESC_HEAD	0x108	/* RO: descriptors completed (free-running) */
#define CAP_REG_DESC_TAIL	0x10c	/* descriptors handed to the block (free-running) */
#define CAP_REG_DESC_ERR_IDX	0x110	/* RO: ring index that raised DESC_ERR */

#define CAP_ID_MAJOR(id)	((id) >> 16)
#define CAP_ID_MINOR(id)	((id) & 0xffff)

#define CAP_CTRL_ENABLE		BIT(0)
#define CAP_CTRL_TEST_PATTERN	BIT(1)	/* word i of frame n = (n & 0xffff) << 16 | i */
#define CAP_CTRL_RESET		BIT(31)	/* self-clearing */

#define CAP_STAT_FRAME_DONE	BIT(0)
#define CAP_STAT_DESC_ERR	BIT(1)	/* prefetched a descriptor without OWN; engine stopped */
#define CAP_STAT_OVERRUN	BIT(2)	/* sample FIFO overflowed; samples were lost */
#define CAP_STAT_IRQ_MASK	(CAP_STAT_FRAME_DONE | CAP_STAT_DESC_ERR | CAP_STAT_OVERRUN)
#define CAP_STAT_BUSY		BIT(8)	/* RO: a descriptor is in progress */

/* Ring descriptor, 16 bytes, little endian, read and written by the block */
struct cap_desc {
	__le32 ctrl;	/* [31] OWN, set by the driver, cleared by the block; [23:0] buffer length */
	__le32 status;	/* written by the block: [31] DONE, [30] ERR, [23:0] bytes written */
	__le32 addr;	/* buffer bus address */
	__le32 seq;	/* written by the block: frame number */
};

#define CAP_DESC_OWN		BIT(31)
#define CAP_DESC_DONE		BIT(31)
#define CAP_DESC_ERR		BIT(30)
#define CAP_DESC_LEN_MASK	GENMASK(23, 0)

#endif /* _ADC_CAPTURE_REGS_H */

