import 'server-only';
import { unstable_cache } from 'next/cache';
import { api } from './api';

export type Role = 'editor' | 'viewer';

export type AccountSummary = {
  userId: string;
  team: string;
  role: Role;
};

// /me takes about 300 ms and the header asks for it on every page load.
export async function getAccountSummary(sid: string): Promise<AccountSummary> {
  const load = unstable_cache(
    () =>
      api<AccountSummary>('/me', {
        headers: { authorization: `Bearer ${sid}` },
      }),
    ['account-summary'],
    { revalidate: 60 },
  );
  return load();
}

--- lib/api.ts ---
import 'server-only';

const BASE_URL = process.env.ADMIN_API_URL ?? 'http://localhost:4000';
const SERVICE_TOKEN = process.env.ADMIN_API_TOKEN ?? '';

export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
  }
}

export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(`${BASE_URL}${path}`, {
    ...init,
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${SERVICE_TOKEN}`,
      ...init.headers,
    },
  });
  if (!res.ok) {
    throw new ApiError(res.status, `${init.method ?? 'GET'} ${path} failed with ${res.status}`);
  }
  return (await res.json()) as T;
}

