import 'server-only';
import { api } from './api';
import { allFields, type SettingsValues } from './settings-schema';

export function getSettings(): Promise<SettingsValues> {
  return api<SettingsValues>('/settings');
}

export function putSettings(values: SettingsValues): Promise<SettingsValues> {
  return api<SettingsValues>('/settings', {
    method: 'PUT',
    body: JSON.stringify(values),
  });
}

type Parsed =
  | { ok: true; values: SettingsValues }
  | { ok: false; errors: Record<string, string> };

export function parseSettings(formData: FormData): Parsed {
  const values: SettingsValues = {};
  const errors: Record<string, string> = {};

  for (const field of allFields) {
    const raw = String(formData.get(field.key) ?? '').trim();
    if (raw === '' && !field.optional) {
      errors[field.key] = 'Required';
      continue;
    }
    switch (field.type) {
      case 'number': {
        const n = Number(raw);
        if (!Number.isFinite(n) || n < field.min || n > field.max) {
          errors[field.key] = `Between ${field.min} and ${field.max}`;
        } else {
          values[field.key] = n;
        }
        break;
      }
      case 'select':
        if (!field.options.some((o) => o.value === raw)) errors[field.key] = 'Not an option';
        else values[field.key] = raw;
        break;
      case 'text':
        if (raw.length > field.maxLength) errors[field.key] = `At most ${field.maxLength} characters`;
        else values[field.key] = raw;
        break;
    }
  }

  return Object.keys(errors).length > 0 ? { ok: false, errors } : { ok: true, values };
}

