import { NextResponse, type NextRequest } from 'next/server';

const SIGN_IN_URL = process.env.SIGN_IN_URL ?? 'https://sso.internal/sign-in';

export function proxy(request: NextRequest) {
  if (!request.cookies.has('sid')) {
    const target = new URL(SIGN_IN_URL);
    target.searchParams.set('return_to', request.nextUrl.pathname);
    return NextResponse.redirect(target);
  }
  return NextResponse.next();
}

export const config = {
  matcher: ['/settings/:path*', '/orders/:path*', '/api/account'],
};

