      <table className="orders">
        <thead>
          <tr>
            <th>Order</th>
            <th>Placed</th>
            <th>Status</th>
            <th>Items</th>
            <th>Total</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((o) => (
            <tr key={o.id}>
              <td>{o.id}</td>
              <td>{o.placedAt.slice(0, 16).replace('T', ' ')}</td>
              <td>{o.status}</td>
              <td>{o.items}</td>
              <td>${o.total.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {to < total && <Link href={`/orders?status=${status}&page=${current + 1}`}>Next page</Link>}
    </section>
  );
}

