#ifndef _ADC_CAPTURE_H
#define _ADC_CAPTURE_H

#include <linux/atomic.h>
#include <linux/clk.h>
#include <linux/device.h>
#include <linux/interrupt.h>
#include <linux/miscdevice.h>
#include <linux/mutex.h>
#include <linux/spinlock.h>
#include <linux/types.h>
#include <linux/wait.h>

#include "capture_regs.h"
#include "uapi/adc_capture.h"

#define CAP_DRV_NAME		"adc-capture"

#define CAP_NUM_BUFS		8			/* ring size: one buffer per descriptor */
#define CAP_FRAME_BYTES		(64 * 1024)		/* 16384 words of 4 x 16-bit samples */
#define CAP_RING_BYTES		(CAP_NUM_BUFS * sizeof(struct cap_desc))
#define CAP_POOL_FRAMES		32			/* frames kept for read() */
#define CAP_RECORD_BYTES	(sizeof(struct adc_capture_hdr) + CAP_FRAME_BYTES)

/* One capture buffer: the block writes the samples into data[] */
struct cap_buf {
	u64 ts_ns;		/* completion time, set by the IRQ thread */
	dma_addr_t dma;		/* bus address of data[] */
	u32 seq;		/* frame number, from the descriptor */
	u32 bytes;		/* bytes written, from the descriptor */
	u32 slot;		/* index in the ring */
	u32 flags;
	u8 data[];
};

#define CAP_BUF_ERR		BIT(0)

struct cap_stats {
	u64 frames;
	u64 desc_err;
	u64 overrun;
	u64 dropped;		/* pool full, frame not kept */
};

struct cap_dev {
	struct device *dev;
	void __iomem *base;
	struct clk *clk;
	int irq;
	bool test_pattern;

	/* descriptor ring, shared with the block */
	struct cap_desc *ring;
	dma_addr_t ring_dma;
	struct cap_buf *bufs[CAP_NUM_BUFS];
	u32 queued;		/* descriptors handed to the block, free-running */
	u32 done;		/* descriptors completed, free-running */
	atomic_t pending;	/* STATUS bits from the hard IRQ for the thread */

	/* frames waiting for read(), single producer (IRQ thread), single consumer */
	u8 *pool;
	unsigned int pool_head;	/* next record to write */
	unsigned int pool_tail;	/* next record to read */
	spinlock_t pool_lock;
	wait_queue_head_t pool_wq;
	struct mutex read_lock;

	struct miscdevice misc;
	struct cap_stats stats;
};

/* capture_dma.c */
int cap_alloc_buffers(struct cap_dev *cd);
void cap_free_buffers(struct cap_dev *cd);
void cap_hw_start(struct cap_dev *cd);
void cap_hw_stop(struct cap_dev *cd);
irqreturn_t cap_irq(int irq, void *data);
irqreturn_t cap_irq_thread(int irq, void *data);

/* capture_cdev.c */
int cap_cdev_register(struct cap_dev *cd);
void cap_cdev_unregister(struct cap_dev *cd);
void cap_pool_push(struct cap_dev *cd, const struct cap_buf *b);

#endif /* _ADC_CAPTURE_H */

--- capture_cdev.c ---
// SPDX-License-Identifier: GPL-2.0
/*
 * /dev/adc-capture0: each read() returns one frame record (header + samples).
 *
 * The IRQ thread copies finished frames into a pool of CAP_POOL_FRAMES
 * records; read() copies the oldest record to user space. When the pool is
 * full, new frames are dropped and counted.
 */

#include <linux/fs.h>
#include <linux/miscdevice.h>
#include <linux/minmax.h>
#include <linux/poll.h>
#include <linux/string.h>
#include <linux/uaccess.h>
#include <linux/vmalloc.h>

#include "capture.h"

static u8 *cap_record(struct cap_dev *cd, unsigned int n)
{
	return cd->pool + (size_t)(n % CAP_POOL_FRAMES) * CAP_RECORD_BYTES;
}

static bool cap_pool_empty(struct cap_dev *cd)
{
	bool empty;

	spin_lock(&cd->pool_lock);
	empty = cd->pool_head == cd->pool_tail;
	spin_unlock(&cd->pool_lock);
	return empty;
}

/* Called from the IRQ thread only. */
void cap_pool_push(struct cap_dev *cd, const struct cap_buf *b)
{
	struct adc_capture_hdr hdr = {
		.seq = b->seq,
		.bytes = min_t(u32, b->bytes, CAP_FRAME_BYTES),
		.ts_ns = b->ts_ns,
	};
	unsigned int head = cd->pool_head;
	bool full;
	u8 *rec;

	spin_lock(&cd->pool_lock);
	full = head - cd->pool_tail == CAP_POOL_FRAMES;
	spin_unlock(&cd->pool_lock);
	if (full) {
		cd->stats.dropped++;
		return;
	}

	rec = cap_record(cd, head);
	memcpy(rec, &hdr, sizeof(hdr));
	memcpy(rec + sizeof(hdr), b->data, hdr.bytes);

	spin_lock(&cd->pool_lock);
	cd->pool_head = head + 1;
	spin_unlock(&cd->pool_lock);
	wake_up_interruptible(&cd->pool_wq);
}

static ssize_t cap_read(struct file *file, char __user *buf, size_t len,
			loff_t *ppos)
{
	struct cap_dev *cd = container_of(file->private_data, struct cap_dev, misc);
	const struct adc_capture_hdr *hdr;
	unsigned int tail;
	ssize_t ret;
	size_t n;

	if (len < CAP_RECORD_BYTES)
		return -EINVAL;

	if (mutex_lock_interruptible(&cd->read_lock))
		return -ERESTARTSYS;

	if (cap_pool_empty(cd) && (file->f_flags & O_NONBLOCK)) {
		ret = -EAGAIN;
		goto out;
	}
	ret = wait_event_interruptible(cd->pool_wq, !cap_pool_empty(cd));
	if (ret)
		goto out;

	tail = cd->pool_tail;
	hdr = (const struct adc_capture_hdr *)cap_record(cd, tail);
	n = sizeof(*hdr) + hdr->bytes;
	if (copy_to_user(buf, hdr, n)) {
		ret = -EFAULT;
		goto out;
	}

	spin_lock(&cd->pool_lock);
	cd->pool_tail = tail + 1;
	spin_unlock(&cd->pool_lock);
	ret = n;
out:
	mutex_unlock(&cd->read_lock);
	return ret;
}

static __poll_t cap_poll(struct file *file, poll_table *wait)
{
	struct cap_dev *cd = container_of(file->private_data, struct cap_dev, misc);

	poll_wait(file, &cd->pool_wq, wait);
	return cap_pool_empty(cd) ? 0 : EPOLLIN | EPOLLRDNORM;
}

static const struct file_operations cap_fops = {
	.owner = THIS_MODULE,
	.read = cap_read,
	.poll = cap_poll,
	.llseek = noop_llseek,
};

int cap_cdev_register(struct cap_dev *cd)
{
	int ret;

	cd->pool = vmalloc(CAP_POOL_FRAMES * CAP_RECORD_BYTES);
	if (!cd->pool)
		return -ENOMEM;

	spin_lock_init(&cd->pool_lock);
	init_waitqueue_head(&cd->pool_wq);
	mutex_init(&cd->read_lock);

	cd->misc.minor = MISC_DYNAMIC_MINOR;
	cd->misc.name = "adc-capture0";
	cd->misc.fops = &cap_fops;
	cd->misc.parent = cd->dev;

	ret = misc_register(&cd->misc);
	if (ret)
		vfree(cd->pool);
	return ret;
}

void cap_cdev_unregister(struct cap_dev *cd)
{
	misc_deregister(&cd->misc);
	vfree(cd->pool);
}

--- capture_dma.c ---
// SPDX-License-Identifier: GPL-2.0
/*
 * ADC capture block: capture buffers, descriptor ring and interrupts.
 *
 * The block owns a ring of CAP_NUM_BUFS descriptors, one per buffer. It
 * fills the buffer of descriptor DESC_HEAD % CAP_NUM_BUFS, writes the
 * descriptor back, increments DESC_HEAD and raises FRAME_DONE. The IRQ
 * thread copies each finished frame into the read() pool and gives the
 * descriptor straight back to the block.
 */

#include <linux/dma-mapping.h>
#include <linux/io.h>
#include <linux/iopoll.h>
#include <linux/ktime.h>
#include <linux/slab.h>

#include "capture.h"

#define CAP_CLKDIV_5MSPS	49	/* 250 MHz / 50 */

int cap_alloc_buffers(struct cap_dev *cd)
{
	int i;

	cd->ring = dma_alloc_coherent(cd->dev, CAP_RING_BYTES, &cd->ring_dma,
				      GFP_KERNEL);
	if (!cd->ring)
		return -ENOMEM;

	for (i = 0; i < CAP_NUM_BUFS; i++) {
		struct cap_buf *b;

		b = kzalloc(sizeof(*b) + CAP_FRAME_BYTES, GFP_KERNEL);
		if (!b)
			goto err;

		b->slot = i;
		b->dma = dma_map_single(cd->dev, b->data, CAP_FRAME_BYTES,
					DMA_TO_DEVICE);
		cd->bufs[i] = b;
	}

	return 0;

err:
	cap_free_buffers(cd);
	return -ENOMEM;
}

void cap_free_buffers(struct cap_dev *cd)
{
	int i;

	for (i = 0; i < CAP_NUM_BUFS; i++) {
		struct cap_buf *b = cd->bufs[i];

		if (!b)
			continue;
		dma_unmap_single(cd->dev, b->dma, CAP_FRAME_BYTES, DMA_TO_DEVICE);
		kfree(b);
		cd->bufs[i] = NULL;
	}

	if (cd->ring) {
		dma_free_coherent(cd->dev, CAP_RING_BYTES, cd->ring, cd->ring_dma);
		cd->ring = NULL;
	}
}

/* Give descriptor idx and its buffer to the block. */
static void cap_queue_buf(struct cap_dev *cd, unsigned int idx)
{
	struct cap_desc *d = &cd->ring[idx];
	struct cap_buf *b = cd->bufs[idx];

	d->addr = cpu_to_le32(b->dma);
	d->seq = 0;
	d->status = 0;
	d->ctrl = cpu_to_le32(CAP_DESC_OWN | CAP_FRAME_BYTES);

	cd->queued++;
	/* once per frame: keep the doorbell cheap */
	writel_relaxed(cd->queued, cd->base + CAP_REG_DESC_TAIL);
}

void cap_hw_start(struct cap_dev *cd)
{
	unsigned int i;
	u32 ctrl = CAP_CTRL_ENABLE;
	u32 val;

	writel(CAP_CTRL_RESET, cd->base + CAP_REG_CTRL);
	if (readl_poll_timeout(cd->base + CAP_REG_CTRL, val,
			       !(val & CAP_CTRL_RESET), 1, 100))
		dev_warn(cd->dev, "reset did not complete\n");

	writel(CAP_FRAME_BYTES, cd->base + CAP_REG_FRAME_BYTES);
	writel(CAP_CLKDIV_5MSPS, cd->base + CAP_REG_CLKDIV);
	writel(lower_32_bits(cd->ring_dma), cd->base + CAP_REG_DESC_BASE);
	writel(CAP_NUM_BUFS, cd->base + CAP_REG_DESC_COUNT);

	cd->queued = 0;
	cd->done = 0;
	for (i = 0; i < CAP_NUM_BUFS; i++)
		cap_queue_buf(cd, i);

	writel(CAP_STAT_IRQ_MASK, cd->base + CAP_REG_STATUS);
	writel(CAP_STAT_IRQ_MASK, cd->base + CAP_REG_IRQ_EN);
	if (cd->test_pattern)
		ctrl |= CAP_CTRL_TEST_PATTERN;
	writel(ctrl, cd->base + CAP_REG_CTRL);
}

void cap_hw_stop(struct cap_dev *cd)
{
	u32 val;

	writel(0, cd->base + CAP_REG_IRQ_EN);
	writel(0, cd->base + CAP_REG_CTRL);
	if (readl_poll_timeout(cd->base + CAP_REG_STATUS, val,
			       !(val & CAP_STAT_BUSY), 1, 1000))
		dev_warn(cd->dev, "block still busy after stop\n");
}

irqreturn_t cap_irq(int irq, void *data)
{
	struct cap_dev *cd = data;
	u32 stat = readl(cd->base + CAP_REG_STATUS) & CAP_STAT_IRQ_MASK;

	if (!stat)
		return IRQ_NONE;

	writel(stat, cd->base + CAP_REG_STATUS);
	atomic_or(stat, &cd->pending);
	return IRQ_WAKE_THREAD;
}

static void cap_desc_error(struct cap_dev *cd)
{
	u32 idx = readl(cd->base + CAP_REG_DESC_ERR_IDX) % CAP_NUM_BUFS;
	struct cap_desc *d = &cd->ring[idx];

	cd->stats.desc_err++;
	dev_err_ratelimited(cd->dev,
			    "descriptor %u not owned by the block (ctrl 0x%08x status 0x%08x addr 0x%08x seq %u), restarting\n",
			    idx, le32_to_cpu(d->ctrl),
			    le32_to_cpu(d->status), le32_to_cpu(d->addr),
			    le32_to_cpu(d->seq));

	/* the engine stopped; the doorbell restarts it from DESC_HEAD */
	writel(cd->queued, cd->base + CAP_REG_DESC_TAIL);
}

/* The frame in descriptor idx is complete: keep it for read(). */
static void cap_complete(struct cap_dev *cd, unsigned int idx)
{
	struct cap_desc *d = &cd->ring[idx];
	struct cap_buf *b = cd->bufs[idx];
	u32 status = le32_to_cpu(d->status);

	b->seq = le32_to_cpu(d->seq);
	b->bytes = status & CAP_DESC_LEN_MASK;
	b->ts_ns = ktime_get_ns();
	b->flags = (status & CAP_DESC_ERR) ? CAP_BUF_ERR : 0;

	cap_pool_push(cd, b);
	cd->stats.frames++;
}

irqreturn_t cap_irq_thread(int irq, void *data)
{
	struct cap_dev *cd = data;
	u32 stat = atomic_xchg(&cd->pending, 0);
	u32 head;

	if (stat & CAP_STAT_OVERRUN)
		cd->stats.overrun++;

	/* readl() orders the descriptor reads below after this register read */
	head = readl(cd->base + CAP_REG_DESC_HEAD);
	while (cd->done != head) {
		unsigned int idx = cd->done % CAP_NUM_BUFS;

		cap_complete(cd, idx);
		cd->done++;
		cap_queue_buf(cd, idx);
	}

	if (stat & CAP_STAT_DESC_ERR)
		cap_desc_error(cd);

	return IRQ_HANDLED;
}

--- capture_main.c ---
// SPDX-License-Identifier: GPL-2.0
/*
 * Platform driver for the ADC capture block in the FPGA fabric.
 *
 * The block streams 4 x 16-bit samples at 5 MS/s into 64 KiB frames and
 * writes them to memory through its own descriptor DMA engine.
 */

#include <linux/clk.h>
#include <linux/dma-mapping.h>
#include <linux/interrupt.h>
#include <linux/io.h>
#include <linux/module.h>
#include <linux/of.h>
#include <linux/platform_device.h>

#include "capture.h"

static bool test_pattern;
module_param(test_pattern, bool, 0444);
MODULE_PARM_DESC(test_pattern, "Capture the block's counting pattern instead of the ADC");

static int cap_probe(struct platform_device *pdev)
{
	struct device *dev = &pdev->dev;
	struct cap_dev *cd;
	u32 id, addr_width;
	int ret;

	cd = devm_kzalloc(dev, sizeof(*cd), GFP_KERNEL);
	if (!cd)
		return -ENOMEM;

	cd->dev = dev;
	cd->test_pattern = test_pattern;
	atomic_set(&cd->pending, 0);

	cd->base = devm_platform_ioremap_resource(pdev, 0);
	if (IS_ERR(cd->base))
		return PTR_ERR(cd->base);

	cd->clk = devm_clk_get_enabled(dev, "s_axi_aclk");
	if (IS_ERR(cd->clk))
		return dev_err_probe(dev, PTR_ERR(cd->clk), "no s_axi_aclk\n");

	cd->irq = platform_get_irq(pdev, 0);
	if (cd->irq < 0)
		return cd->irq;

	id = readl(cd->base + CAP_REG_ID);
	if (CAP_ID_MAJOR(id) != 1)
		return dev_err_probe(dev, -ENODEV, "unsupported IP version 0x%08x\n", id);

	if (of_property_read_u32(dev->of_node, "lab,addr-width", &addr_width))
		addr_width = 32;
	ret = dma_set_mask_and_coherent(dev, DMA_BIT_MASK(addr_width));
	if (ret)
		return dev_err_probe(dev, ret, "no usable DMA mask for %u bits\n", addr_width);

	ret = cap_alloc_buffers(cd);
	if (ret)
		return ret;

	ret = cap_cdev_register(cd);
	if (ret)
		goto err_free;

	ret = devm_request_threaded_irq(dev, cd->irq, cap_irq, cap_irq_thread,
					IRQF_ONESHOT, dev_name(dev), cd);
	if (ret)
		goto err_cdev;

	platform_set_drvdata(pdev, cd);
	cap_hw_start(cd);

	dev_info(dev, "IP v%u.%u, %d buffers of %d bytes, ring at %pad, buffer 0 at %pad\n",
		 CAP_ID_MAJOR(id), CAP_ID_MINOR(id), CAP_NUM_BUFS, CAP_FRAME_BYTES,
		 &cd->ring_dma, &cd->bufs[0]->dma);
	return 0;

err_cdev:
	cap_cdev_unregister(cd);
err_free:
	cap_free_buffers(cd);
	return ret;
}

static void cap_remove(struct platform_device *pdev)
{
	struct cap_dev *cd = platform_get_drvdata(pdev);

	cap_cdev_unregister(cd);
	cap_hw_stop(cd);
	cap_free_buffers(cd);
	clk_disable_unprepare(cd->clk);
}

static const struct of_device_id cap_of_match[] = {
	{ .compatible = "lab,adc-capture-1.2" },
	{ /* sentinel */ }
};
MODULE_DEVICE_TABLE(of, cap_of_match);

static struct platform_driver cap_driver = {
	.probe = cap_probe,
	.remove = cap_remove,
	.driver = {
		.name = CAP_DRV_NAME,
		.of_match_table = cap_of_match,
	},
};
module_platform_driver(cap_driver);

MODULE_DESCRIPTION("ADC capture block driver");
MODULE_LICENSE("GPL");

