// Exercise 1: tuple patterns, ranges, guards and @ bindings.
// Run: rustc --edition 2024 --test -o main ex1_scores.rs && ./main --test-threads=4
//
// Replace the todo!() with ONE match on `(score, late)`. Scores are 0 to 100.
// Rules, checked in this order:
//   100, on time                   -> "perfect"
//   90 to 99, on time              -> "top 93"     (the score)
//   0 to 49, on time or late       -> "fail"
//   late, and score is even        -> "late even 62"
//   anything else                  -> "pass 71"
// Use a range with @ for "top", a range for "fail", and a guard for "late even".

fn grade(score: u8, late: bool) -> String {
    match (score, late) {
        (100, false) => String::from("perfect"),
        (s @ 90..=99, false) => format!("top {s}"),
        (0..=49, _) => String::from("fail"),
        (s, true) if s % 2 == 0 => format!("late even {s}"),
        (s, _) => format!("pass {s}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn on_time_grades() {
        assert_eq!(grade(100, false), "perfect");
        assert_eq!(grade(93, false), "top 93");
        assert_eq!(grade(90, false), "top 90");
        assert_eq!(grade(71, false), "pass 71");
    }

    #[test]
    fn fail_wins_over_late_even() {
        assert_eq!(grade(49, false), "fail");
        assert_eq!(grade(48, true), "fail");
        assert_eq!(grade(0, true), "fail");
    }

    #[test]
    fn late_grades() {
        assert_eq!(grade(62, true), "late even 62");
        assert_eq!(grade(100, true), "late even 100");
        assert_eq!(grade(95, true), "pass 95");
    }
}


