Subject: [PATCH] qadc: move all interrupt work to the IRQ thread

The debug kernel complains about the hard handler (might_sleep and lockdep,
both on the mutex taken from qadc_hardirq), and lockdep also reports st->lock
taken from sysfs with interrupts enabled.

Drop qadc_hardirq and do everything in the IRQ thread, with a NULL primary
handler and IRQF_ONESHOT, which the core now accepts. The timestamp is taken
at the start of the thread.

Nothing touches st->lock from hard interrupt context any more, so make it a
mutex everywhere: the IRQ thread, sysfs and the watchdog.

On remove, cancel the reset work and delete the watchdog timer before
stopping conversions.

Tested on the debug kernel:
- /proc/interrupts: about 200 interrupts per second on line 63
- tests/stall_test.sh 1-0048 1-0049: PASS
- tests/unbind_loop.sh 1-0048 50: 50 of 50, no crash
---
 qadc-core.c  | 46 ++++++++++++++++++----------------------------
 qadc-sysfs.c |  5 ++---
 qadc.h       |  4 +---
 3 files changed, 21 insertions(+), 34 deletions(-)

diff --git a/qadc-core.c b/qadc-core.c
index baf8f28..419361c 100644
--- a/qadc-core.c
+++ b/qadc-core.c
@@ -62,26 +62,12 @@ void qadc_wdog_kick(struct qadc *st)
 	mod_timer(&st->wdog, jiffies + qadc_wdog_period(st));
 }

-static irqreturn_t qadc_hardirq(int irq, void *data)
-{
-	struct qadc *st = data;
-
-	spin_lock(&st->lock);
-	st->irq_ts_ns = ktime_get_ns();
-	st->irqs++;
-	spin_unlock(&st->lock);
-
-	qadc_wdog_kick(st);
-
-	return IRQ_WAKE_THREAD;
-}
-
 static irqreturn_t qadc_irq_thread(int irq, void *data)
 {
 	struct qadc *st = data;
 	struct qadc_sample *s;
 	__be16 raw[QADC_NUM_CH];
-	unsigned long flags;
+	u64 ts = ktime_get_ns();
 	int ret, i;

 	ret = i2c_smbus_read_i2c_block_data(st->client, QADC_REG_DATA,
@@ -91,14 +77,17 @@ static irqreturn_t qadc_irq_thread(int irq, void *data)
 		return IRQ_HANDLED;
 	}

-	spin_lock_irqsave(&st->lock, flags);
+	mutex_lock(&st->lock);
+	st->irqs++;
 	s = &st->ring[st->head];
-	s->ts_ns = st->irq_ts_ns;
+	s->ts_ns = ts;
 	for (i = 0; i < QADC_NUM_CH; i++)
