 	if (ret < 0)
@@ -162,12 +151,12 @@ static int qadc_probe(struct i2c_client *client)

 	/*
 	 * Both ADCs drive the same RDY line (see dts/), so the IRQ is shared.
-	 * request_threaded_irq() refuses a NULL primary handler here
-	 * ("Threaded irq requested with handler=NULL and !ONESHOT"),
-	 * so we pass qadc_hardirq.
+	 * All the work, the I2C read included, is done in the IRQ thread;
+	 * IRQF_ONESHOT keeps the line masked until the threads have run.
 	 */
-	ret = devm_request_threaded_irq(dev, client->irq, qadc_hardirq,
-					qadc_irq_thread, IRQF_SHARED,
+	ret = devm_request_threaded_irq(dev, client->irq, NULL,
+					qadc_irq_thread,
+					IRQF_SHARED | IRQF_ONESHOT,
 					dev_name(dev), st);
 	if (ret)
 		return dev_err_probe(dev, ret, "cannot request IRQ %d\n",
@@ -194,11 +183,12 @@ static void qadc_remove(struct i2c_client *client)
 {
