# Reads the newest sample from both ADCs every 100 ms and prints one line
# per ADC. Runs on the device in production.
while true; do
	for dev in 1-0048 1-0049; do
		printf '%s %s\n' "$dev" "$(cat /sys/bus/i2c/devices/$dev/latest)"
	done
	sleep 0.1
done

