#!/bin/sh
# Unbinds and rebinds the driver from one ADC, N times.
# Usage: unbind_loop.sh 1-0048 50
dev=${1:-1-0048}
n=${2:-50}
drv=/sys/bus/i2c/drivers/qadc

i=1
while [ "$i" -le "$n" ]; do
	echo "$dev" > "$drv/unbind"
	sleep 0.2
	echo "$dev" > "$drv/bind"
	sleep 0.3
	echo "iteration $i: ok"
	i=$((i + 1))
done

