trait Meter {
    fn value(&self) -> u32;
    fn unit(&self) -> String {
        String::from("units")
    }
    fn report(&self) -> String {
        format!("{} {}", self.value(), self.unit())
    }
}

struct Count(u32);
struct Bytes(u32);

impl Meter for Count {
    fn value(&self) -> u32 {
        self.0
    }
}

impl Meter for Bytes {
    fn value(&self) -> u32 {
        self.0 / 1024
    }
    fn unit(&self) -> String {
        String::from("KiB")
    }
}

fn main() {
    let meters: Vec<Box<dyn Meter>> = vec![Box::new(Count(3)), Box::new(Bytes(4096)), Box::new(Count(9))];
    for m in &meters {
        println!("{}", m.report());
    }
}
