fn rises(items: &[i32]) -> u32 {
    match items {
        [] | [_] => 0,
        [a, b, rest @ ..] => {
            let inc = if b > a { 1 } else { 0 };
            inc + rises(&[*b].iter().copied().chain(rest.iter().copied()).collect::<Vec<_>>())
        }
    }
}

