'use client';

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';

export type ClientAccount = { userId: string; team: string; role: 'editor' | 'viewer' };

const AccountContext = createContext<ClientAccount | null>(null);

export function AccountProvider({ children }: { children: ReactNode }) {
  const [account, setAccount] = useState<ClientAccount | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('/api/account')
      .then((res) => (res.ok ? res.json() : null))
      .then((data: ClientAccount | null) => {
        if (!cancelled) setAccount(data);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return <AccountContext.Provider value={account}>{children}</AccountContext.Provider>;
}

export function useAccount() {
  return useContext(AccountContext);
}

export function AccountBadge() {
  const account = useAccount();
  if (!account) return <span className="badge muted">Signing in…</span>;
  return (
    <span className="badge" data-testid="account-badge">
      {account.userId} · {account.team} · {account.role}
    </span>
  );
}

