import 'server-only';
import { unstable_cache } from 'next/cache';
import { api } from './api';

export type Role = 'editor' | 'viewer';

export type AccountSummary = {
  userId: string;
  team: string;
  role: Role;
};

// /me takes about 300 ms and the header asks for it on every page load.
export async function getAccountSummary(sid: string): Promise<AccountSummary> {
  const load = unstable_cache(
    () =>
      api<AccountSummary>('/me', {
        headers: { authorization: `Bearer ${sid}` },
      }),
    ['account-summary'],
    { revalidate: 60 },
  );
  return load();
}

