#[derive(Debug)]
enum Slot {
    Full { label: String, count: u32 },
    Empty,
}

fn a(slot: &Slot) {
    if let Slot::Full { label, count } = slot {
        println!("A {label} {count}");
    }
}

fn b(slot: &Slot) {
    if let Slot::Full { label, count } = *slot {
        println!("B {label} {count}");
    }
}

fn c(slot: &Slot) {
    if let Slot::Full { ref label, count } = *slot {
        println!("C {label} {count}");
    }
}

fn d(slot: &Slot) {
    if let Slot::Full { ref label, .. } = slot {
        println!("D {label}");
    }
}

// Goal: add 1 to the slot's count.
fn e(slot: &mut Slot) {
    if let &mut Slot::Full { mut count, .. } = slot {
        count += 1;
        println!("E {count}");
    }
}

fn main() {
    let mut s = Slot::Full { label: String::from("x"), count: 1 };
    a(&s);
    b(&s);
    c(&s);
    d(&s);
    e(&mut s);
    println!("{s:?}");
}
