fn shape(items: &[i32]) -> String {
    match items {
        [] => String::from("empty"),
        [x] => format!("one: {x}"),
        [first, .., last] if first == last => format!("same ends: {first}"),
        [first, rest @ ..] => format!("{first} then {} more", rest.len()),
    }
}

// TODO: count how many times a value is bigger than the one before it.
// Use a slice pattern and recursion. No indexing with [i].
fn rises(items: &[i32]) -> u32 {
    match items {
        [] | [_] => 0,
        [a, b, rest @ ..] => {
            let add = if b > a { 1 } else { 0 };
            add + rises(&[b].iter().chain(rest.iter()).copied().collect::<Vec<_>>())
        }
    }
}

fn main() {
    let data = [7, 1, 2, 7];
    println!("{}", shape(&data));
    println!("{}", shape(&data[..2]));
    println!("{}", rises(&[1, 3, 2, 5, 5, 6])); // expect 3
    println!("{}", rises(&[4]));                // expect 0
}
