#ifndef _QADC_H
#define _QADC_H

#include <linux/bits.h>
#include <linux/i2c.h>
#include <linux/mutex.h>
#include <linux/spinlock.h>
#include <linux/sysfs.h>
#include <linux/timer.h>
#include <linux/types.h>
#include <linux/workqueue.h>

#define QADC_REG_STATUS		0x00
#define  QADC_STATUS_DRDY	BIT(0)
#define  QADC_STATUS_OVR	BIT(1)
#define QADC_REG_CONFIG		0x01
#define  QADC_CONFIG_ODR_MASK	GENMASK(2, 0)
#define  QADC_CONFIG_CONT	BIT(7)
#define QADC_REG_DATA		0x02	/* CH0..CH3, 16-bit big-endian */
#define QADC_REG_ID		0x0f
#define  QADC_ID_VALUE		0x5a

#define QADC_NUM_CH		4
#define QADC_RING_LEN		256	/* power of two */
#define QADC_DEFAULT_ODR_HZ	100
#define QADC_WDOG_MISSED	8	/* periods without a conversion */

struct qadc_sample {
	u64 ts_ns;
	u16 ch[QADC_NUM_CH];
};

struct qadc {
	struct i2c_client *client;
	struct device *dev;

	struct mutex cfg_lock;		/* odr_hz, CONFIG writes */
	unsigned int odr_hz;

	spinlock_t lock;		/* protects the fields below */
	struct qadc_sample ring[QADC_RING_LEN];
	unsigned int head;		/* next slot to write */
	u64 irq_ts_ns;			/* time of the last RDY interrupt */
	u64 samples;
	unsigned long irqs;
	unsigned long resets;

	struct timer_list wdog;
	struct work_struct reset_work;
};

int qadc_hw_config(struct qadc *st, unsigned int odr_hz);
bool qadc_odr_valid(unsigned int odr_hz);
unsigned long qadc_wdog_period(struct qadc *st);
void qadc_wdog_kick(struct qadc *st);

extern const struct attribute_group *qadc_groups[];

#endif /* _QADC_H */

--- tests/stall_test.sh ---
#!/bin/sh
# Stops conversions on the listed ADCs behind the driver's back, then checks
# that the watchdog restarted them.
# Usage: stall_test.sh 1-0048 [1-0049]
set -e

counter() { sed -n "s/^$2 //p" "/sys/bus/i2c/devices/$1/stats"; }

for dev in "$@"; do
	eval "resets_${dev#*-}=$(counter "$dev" resets)"
	echo "stopping conversions on 0x${dev#*-00} (CONFIG = 0x00)"
	i2cset -f -y "${dev%%-*}" "0x${dev#*-00}" 0x01 0x00
done

sleep 0.5

status=0
for dev in "$@"; do
	before=$(eval echo "\$resets_${dev#*-}")
	after=$(counter "$dev" resets)
	if [ "$after" -gt "$before" ]; then
		echo "$dev: PASS (resets $before -> $after)"
	else
		echo "$dev: FAIL (resets $before -> $after)"
		status=1
	fi
done
exit $status

