#ifndef _UAPI_ADC_CAPTURE_H
#define _UAPI_ADC_CAPTURE_H

#include <linux/types.h>

struct adc_capture_hdr {
	__u32 seq;	/* frame number, counted by the block from ENABLE */
	__u32 bytes;	/* bytes of samples that follow */
	__u64 ts_ns;	/* CLOCK_MONOTONIC time the driver saw the frame complete */
};

#endif /* _UAPI_ADC_CAPTURE_H */

