# SPDX-License-Identifier: (GPL-2.0-only OR BSD-2-Clause)
%YAML 1.2
---
$id: http://devicetree.org/schemas/iio/adc/lab,adc-capture.yaml#
$schema: http://devicetree.org/meta-schemas/core.yaml#

title: ADC capture block with descriptor DMA (FPGA IP)

description:
  Samples 4 ADC channels at 16 bits and writes 64 KiB frames to memory
  through its own descriptor DMA engine. The register file and the DMA
  engine registers share one 4 KiB window.

properties:
  compatible:
    const: lab,adc-capture-1.2

  reg:
    maxItems: 1

  interrupts:
    maxItems: 1

  clocks:
    maxItems: 1

  clock-names:
    const: s_axi_aclk

  lab,addr-width:
    $ref: /schemas/types.yaml#/definitions/uint32
    description: Width of the AXI master address bus.
    enum: [32]
    default: 32

  dma-coherent: true

required:
  - compatible
  - reg
  - interrupts
  - clocks
  - clock-names

additionalProperties: false

examples:
  - |
    #include <dt-bindings/interrupt-controller/arm-gic.h>

    capture@a0010000 {
        compatible = "lab,adc-capture-1.2";
        reg = <0xa0010000 0x1000>;
        interrupts = <GIC_SPI 89 IRQ_TYPE_LEVEL_HIGH>;
        clocks = <&clkc 71>;
        clock-names = "s_axi_aclk";
    };

