import Link from 'next/link';
import { getOrders } from '@/lib/orders';
import { getSettings } from '@/lib/settings';

type Search = { status?: string; page?: string };

export default async function OrdersPage({ searchParams }: { searchParams: Promise<Search> }) {
  const settings = await getSettings();
  const { status = String(settings.defaultStatusFilter), page = '1' } = await searchParams;
  const pageSize = Number(settings.ordersPageSize);
  const current = Math.max(1, Number(page) || 1);
  const { total, rows } = await getOrders({ status, page: current, limit: pageSize });
  const from = total === 0 ? 0 : (current - 1) * pageSize + 1;
  const to = Math.min(current * pageSize, total);

  return (
    <section>
      {settings.maintenanceBanner && <p className="banner">{settings.maintenanceBanner}</p>}
      <h1>Orders</h1>
      <p className="muted">
        Showing {from} to {to} of {total} ({status})
      </p>
      <table className="orders">
        <thead>
          <tr>
            <th>Order</th>
            <th>Placed</th>
            <th>Status</th>
            <th>Items</th>
            <th>Total</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((o) => (
            <tr key={o.id}>
              <td>{o.id}</td>
              <td>{o.placedAt.slice(0, 16).replace('T', ' ')}</td>
              <td>{o.status}</td>
              <td>{o.items}</td>
              <td>${o.total.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {to < total && <Link href={`/orders?status=${status}&page=${current + 1}`}>Next page</Link>}
    </section>
  );
}

--- app/settings/actions.ts ---
'use server';

import { parseSettings, putSettings } from '@/lib/settings';

export type SaveState =
  | { status: 'idle' }
  | { status: 'saved'; savedAt: string }
  | { status: 'invalid'; errors: Record<string, string> };

export async function saveSettings(_prev: SaveState, formData: FormData): Promise<SaveState> {
  const parsed = parseSettings(formData);
  if (!parsed.ok) {
    return { status: 'invalid', errors: parsed.errors };
  }

  await putSettings(parsed.values);

  return { status: 'saved', savedAt: new Date().toISOString() };
}

