fn b(slot: &Slot) {
    if let Slot::Full { label, count } = *slot {
        println!("B {label} {count}");
    }
}

fn c(slot: &Slot) {
    if let Slot::Full { ref label, count } = *slot {
        println!("C {label} {count}");
    }
}

fn d(slot: &Slot) {
    if let Slot::Full { ref label, .. } = slot {
        println!("D {label}");
    }
}

