// Goal: keep `shapes` as it is and get a scaled copy in `bigger`.
trait Shape {
    fn area(&self) -> f64;
    fn scale(&mut self, k: f64);
}

#[derive(Clone)]
struct Square(f64);

#[derive(Clone)]
struct Circle(f64);

impl Shape for Square {
    fn area(&self) -> f64 { self.0 * self.0 }
    fn scale(&mut self, k: f64) { self.0 *= k; }
}

impl Shape for Circle {
    fn area(&self) -> f64 { 3.0 * self.0 * self.0 }
    fn scale(&mut self, k: f64) { self.0 *= k; }
}

fn total(list: &[Box<dyn Shape>]) -> f64 {
    list.iter().map(|s| s.area()).sum()
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![Box::new(Square(2.0)), Box::new(Circle(1.0))];
    let mut bigger = shapes.clone();
    for s in bigger.iter_mut() {
        s.scale(2.0);
    }
    println!("{} {}", total(&shapes), total(&bigger));
}
