// Exercise 3: what names bind to when you match through & and &mut.
// Run: rustc --edition 2024 --test -o main ex3_slots.rs && ./main --test-threads=4
//
// Replace the three todo!()s. No clone() anywhere.

#[derive(Debug, PartialEq)]
enum Slot {
    Full { label: String, count: u32 },
    Empty,
}

/// Length of the label, or 0 for an empty slot. Reads through a shared reference.
fn label_len(slot: &Slot) -> usize {
    match slot {
        Slot::Full { label, .. } => label.len(), // label: &String
        Slot::Empty => 0,
    }
}

/// Add `n` to the count of a full slot, in place. Empty slots stay empty.
fn add(slot: &mut Slot, n: u32) {
    if let Slot::Full { count, .. } = slot {
        *count += n; // count: &mut u32
    }
}

/// Take the slot apart: give back the label of a full slot, None for empty.
/// The slot is consumed, so the String can move out without cloning.
fn into_label(slot: Slot) -> Option<String> {
    match slot {
        Slot::Full { label, .. } => Some(label), // label: String, moved out
        Slot::Empty => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn full(label: &str, count: u32) -> Slot {
        Slot::Full { label: label.to_string(), count }
    }

    #[test]
    fn reads_label_length() {
        assert_eq!(label_len(&full("abc", 1)), 3);
        assert_eq!(label_len(&Slot::Empty), 0);
    }

    #[test]
    fn adds_in_place() {
        let mut s = full("a", 1);
        add(&mut s, 4);
        assert_eq!(s, full("a", 5));
        let mut e = Slot::Empty;
        add(&mut e, 4);
        assert_eq!(e, Slot::Empty);
    }

    #[test]
    fn moves_the_label_out() {
        assert_eq!(into_label(full("box", 2)), Some(String::from("box")));
        assert_eq!(into_label(Slot::Empty), None);
    }
}



