struct Signal {
    // Option, so `advance` can take() the old state out.
    light: Option<Box<dyn Light>>,
}

impl Signal {
    // 2. A new signal starts at red.
    fn new() -> Signal {
        Signal { light: Some(Box::new(Red)) }
    }

    // 3. Move to the next light.
    fn advance(&mut self) {
        let current = self.light.take().unwrap();
        self.light = Some(current.next());
    }

    fn color(&self) -> &'static str {
        self.light.as_ref().unwrap().color()
    }

    // 4. Total seconds for `n` lights, starting with the current one.
    //    The signal ends up `n` lights further on.
    fn run_for(&mut self, n: usize) -> u32 {
        let mut total = 0;
        for _ in 0..n {
            total += self.light.as_ref().unwrap().seconds();
            self.advance();
        }
        total
    }
}

