fn shape(items: &[i32]) -> String {
    match items {
        [] => String::from("empty"),
        [x] => format!("single {x}"),
        [first, rest @ .., last] => format!("first {first}, rest_len {}, last {last}", rest.len()),
    }
}

fn rises(items: &[i32]) -> bool {
    match items {
        [] | [_] => true,
        [a, b, rest @ ..] if a <= b => rises(&items[1..]),
        [_, _] => false,
        _ => false,
    }
}

fn main() {
    let a = [1, 2, 3, 4];
    let b = [1, 1, 2];
    let c = [3, 2, 1];

    println!("{}", shape(&a));
    println!("{}", shape(&[7]));
    println!("{}", shape(&[]));

    println!("{}", rises(&a));
    println!("{}", rises(&b));
    println!("{}", rises(&c));
}
