fn rises(items: &[i32]) -> u32 {
    match items {
        [] | [_] => 0,
        [a, b, rest @ ..] => {
            let count = if b > a { 1 } else { 0 };
            count + rises(&[b]) + rises(rest)
        }
    }
}

