#[derive(Debug, PartialEq)]
enum Entry {
    File { name: String, size: u64 },
    Dir { name: String, children: u32 },
    Link,
}

/// Add `by` to the size of every File, in place. Dirs and Links are unchanged.
fn grow_files(entries: &mut [Entry], by: u64) {
    for entry in entries {
        // entry: &mut Entry, so `size` binds as &mut u64
        if let Entry::File { size, .. } = entry {
            *size += by;
        }
    }
}

/// Total size of all Files.
fn total_size(entries: &[Entry]) -> u64 {
    let mut total = 0;
    for entry in entries {
        if let Entry::File { size, .. } = entry {
            total += size; // size: &u64
        }
    }
    total
}

/// The names of every File and Dir, in order, joined with ",". Links have no name.
/// Use one arm for both Files and Dirs.
fn names(entries: &[Entry]) -> String {
    let mut out = String::new();
    for entry in entries {
        match entry {
            Entry::File { name, .. } | Entry::Dir { name, .. } => {
                if !out.is_empty() {
                    out.push(',');
                }
                out.push_str(name); // name: &String
            }
            Entry::Link => {}
        }
    }
    out
}

fn main() {
    let mut entries = [
        Entry::File { name: String::from("a.txt"), size: 10 },
        Entry::Link,
        Entry::Dir { name: String::from("docs"), children: 3 },
        Entry::File { name: String::from("b.txt"), size: 5 },
    ];
    grow_files(&mut entries, 100);
    println!("total {}", total_size(&entries));
    println!("names {}", names(&entries));
}

