// Replace both todo!()s using slice patterns ([], [x], [first, .., last],
// [head, rest @ ..]). No indexing with [i] and no .len() checks.

/// "empty", "one 5", "pair 1 2", or "from 1 to 9" for three or more items.
fn summary(items: &[i32]) -> String {
    match items {
        [] => String::from("empty"),
        [x] => format!("one {x}"),
        [a, b] => format!("pair {a} {b}"),
        [first, .., last] => format!("from {first} to {last}"),
    }
}

/// True when the letters read the same backwards. Empty and one-letter
/// slices are palindromes. Use recursion on the middle part.
fn is_palindrome(letters: &[char]) -> bool {
    match letters {
        [] | [_] => true,
        [first, middle @ .., last] => first == last && is_palindrome(middle),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn summaries_by_length() {
        assert_eq!(summary(&[]), "empty");
        assert_eq!(summary(&[5]), "one 5");
        assert_eq!(summary(&[1, 2]), "pair 1 2");
        assert_eq!(summary(&[1, 4, 4, 9]), "from 1 to 9");
    }

    #[test]
    fn palindromes() {
        assert!(is_palindrome(&[]));
        assert!(is_palindrome(&['a']));
        assert!(is_palindrome(&['a', 'b', 'a']));
        assert!(is_palindrome(&['x', 'y', 'y', 'x']));
    }

    #[test]
    fn not_palindromes() {
        assert!(!is_palindrome(&['a', 'b']));
        assert!(!is_palindrome(&['a', 'b', 'c', 'b', 'x']));
    }
}


